import { useCallback, useEffect, useMemo, useState, type ChangeEvent, type FormEvent, type ReactNode } from 'react';
import { ChevronDown, ChevronLeft, ChevronRight, Crown, Edit3, Eye, Flag, Heart, Home, ImagePlus, LayoutGrid, LogOut, MapPin, MessageCircle, Moon, MoreHorizontal, Phone, Plus, Search, Send, ShoppingBag, SlidersHorizontal, Sun, Trash2, UserRound, Wrench, Hammer, X } from 'lucide-react';
import { PeidaLogo, PeidaMark } from './Logo';
import Onboarding from './Onboarding';
import MessagesScreen from './Messages';
import { uploadImage, uploadImages } from './upload';
import { CATEGORIES, categoryKeys, categoryMatches, countiesByProvince, fnum, locations, PLACEHOLDER_IMAGE, provinces, toman, type Ad, type Category, type Comment, type Filters, type StoryItem, type User } from './data';

type Page = 'home' | 'browse' | 'categories' | 'detail' | 'post' | 'profile' | 'manage' | 'messages' | 'saved' | 'admin';
type LocationValue = { province: string; county: string; village: string };
const SESSION_KEY = 'peida-user';
const emptyFilters: Filters = { category: 'همه', province: '', county: '', village: '', minPrice: '', maxPrice: '', sort: 'newest' };
function readSession(): User | null { try { const raw = localStorage.getItem(SESSION_KEY); return raw ? JSON.parse(raw) as User : null; } catch { return null; } }

function Field({ title, children }: { title: string; children: ReactNode }) { return <label className="block"><b className="mb-2 block text-sm">{title}</b>{children}</label>; }
function Sheet({ title, close, children, testId }: { title: string; close: () => void; children: ReactNode; testId: string }) { return <div className="fixed inset-0 z-[60] grid place-items-end bg-black/45 sm:place-items-center"><div data-testid={testId} className="max-h-[92dvh] w-full max-w-xl overflow-y-auto rounded-t-3xl bg-white p-5 pb-[calc(1.25rem+env(safe-area-inset-bottom))] dark:bg-[#17211e] sm:rounded-3xl"><div className="mb-5 flex items-center justify-between"><b>{title}</b><button data-testid="close-sheet" onClick={close} className="grid size-10 place-items-center rounded-xl hover:bg-zinc-100 dark:hover:bg-white/10"><X /></button></div>{children}</div></div>; }
function CategoryArt({ item, className }: { item: Category; className: string }) { const Icon = item.icon === 'wrench' ? Wrench : item.icon === 'hammer' ? Hammer : ShoppingBag; return item.image ? <img src={item.image} alt={item.key} className={'object-cover ' + className} /> : <span className={'grid place-items-center bg-emerald-50 text-[#12a05c] dark:bg-emerald-950/30 ' + className}><Icon size={20} /></span>; }

function LocationInputs({ value, onChange, ids }: { value: LocationValue; onChange: (value: LocationValue) => void; ids: [string, string, string] }) {
  const counties = value.province ? countiesByProvince[value.province] || [] : [];
  const villages = value.province && value.county ? locations[value.province]?.[value.county] || [] : [];
  return <div className="grid gap-3 sm:grid-cols-3">
    <Field title="استان"><select data-testid={ids[0]} className="input" value={value.province} onChange={(e) => onChange({ province: e.target.value, county: '', village: '' })}><option value="">همه استان‌ها</option>{provinces.map((name) => <option key={name} value={name}>{name}</option>)}</select></Field>
    <Field title="شهر / شهرستان"><input data-testid={ids[1]} list={ids[1] + '-options'} disabled={!value.province} className="input" value={value.county} onChange={(e) => onChange({ ...value, county: e.target.value, village: '' })} placeholder={value.province ? 'انتخاب یا نوشتن نام شهرستان' : 'ابتدا استان را انتخاب کنید'} /><datalist id={ids[1] + '-options'}>{counties.map((name) => <option key={name} value={name} />)}</datalist></Field>
    <Field title="روستا / بخش"><input data-testid={ids[2]} list={ids[2] + '-options'} disabled={!value.county} className="input" value={value.village} onChange={(e) => onChange({ ...value, village: e.target.value })} placeholder={value.county ? 'انتخاب یا نوشتن نام روستا' : 'ابتدا شهرستان را انتخاب کنید'} /><datalist id={ids[2] + '-options'}>{villages.map((name) => <option key={name} value={name} />)}</datalist></Field>
  </div>;
}
function ImagePicker({ files, setFiles, testId, existing = [], removeExisting, single = false }: { files: File[]; setFiles: (files: File[]) => void; testId: string; existing?: string[]; removeExisting?: (image: string) => void; single?: boolean }) {
  const [previews, setPreviews] = useState<string[]>([]);
  useEffect(() => { const urls = files.map((file) => URL.createObjectURL(file)); setPreviews(urls); return () => urls.forEach(URL.revokeObjectURL); }, [files]);
  const choose = (event: ChangeEvent<HTMLInputElement>) => { const picked = Array.from(event.target.files || []); if (picked.length) setFiles(single ? picked.slice(0, 1) : [...files, ...picked].slice(0, 6)); event.target.value = ''; };
  return <div><label data-testid={testId} className="flex min-h-28 cursor-pointer flex-col items-center justify-center rounded-2xl border-2 border-dashed border-emerald-300 bg-emerald-50/70 px-3 text-center dark:border-emerald-800 dark:bg-emerald-950/20"><ImagePlus className="text-[#12a05c]" /><b className="mt-2 text-sm">{single ? 'انتخاب تصویر' : 'افزودن تصویر'}</b><span className="mt-1 text-xs text-zinc-500">{single ? 'یک تصویر تا ۵ مگابایت' : 'تا ۶ تصویر، هر تصویر تا ۵ مگابایت'}</span><input type="file" accept="image/*" multiple={!single} className="hidden" onChange={choose} /></label>{(existing.length > 0 || previews.length > 0) && <div className="mt-3 grid grid-cols-4 gap-2">{existing.map((image) => <span key={image} className="relative"><img src={image} alt="تصویر فعلی" className="aspect-square w-full rounded-xl object-cover" />{removeExisting && <button type="button" data-testid="remove-existing-image" onClick={() => removeExisting(image)} className="absolute left-1 top-1 grid size-6 place-items-center rounded-full bg-black/60 text-white"><X size={12} /></button>}</span>)}{previews.map((url, index) => <span key={url} className="relative"><img src={url} alt="پیش‌نمایش" className="aspect-square w-full rounded-xl object-cover" /><button type="button" data-testid={'remove-image-' + index} onClick={() => setFiles(files.filter((_, i) => i !== index))} className="absolute left-1 top-1 grid size-6 place-items-center rounded-full bg-black/60 text-white"><X size={12} /></button></span>)}</div>}</div>;
}

export default function App() {
  const [page, setPage] = useState<Page>(window.location.pathname === '/admin' ? 'admin' : 'home');
  const [ads, setAds] = useState<Ad[]>([]); const [stories, setStories] = useState<StoryItem[]>([]); const [loading, setLoading] = useState(true); const [failed, setFailed] = useState(false);
  const [me, setMe] = useState<User | null>(readSession); const [selected, setSelected] = useState<Ad | null>(null); const [comments, setComments] = useState<Comment[]>([]);
  const [query, setQuery] = useState(''); const [filters, setFilters] = useState<Filters>(emptyFilters); const [saved, setSaved] = useState<number[]>(() => { try { return JSON.parse(localStorage.getItem('peida-saved') || '[]') as number[]; } catch { return []; } });
  const [dark, setDark] = useState(localStorage.getItem('peida-theme') === 'dark'); const [unread, setUnread] = useState(0); const [cityOpen, setCityOpen] = useState(false); const [filterOpen, setFilterOpen] = useState(false); const [composer, setComposer] = useState(false); const [storyIndex, setStoryIndex] = useState<number | null>(null); const [editing, setEditing] = useState<Ad | null>(null); const [pendingChat, setPendingChat] = useState<number | null>(null); const [toast, setToast] = useState('');
  const notify = (text: string) => setToast(text);
  const loadListings = useCallback(async () => { setLoading(true); try { const response = await fetch('/api/listings'); if (!response.ok) throw new Error(); setAds(await response.json()); setFailed(false); } catch { setFailed(true); } finally { setLoading(false); } }, []);
  const loadStories = useCallback(async () => { try { const response = await fetch('/api/stories'); if (response.ok) setStories(await response.json()); } catch { /* stories retain last safe state */ } }, []);
  const loadUnread = useCallback(async () => { if (!me) return; try { const response = await fetch('/api/conversations/unread?userId=' + me.id); if (response.ok) { const data = await response.json() as { count: number }; setUnread(data.count); } } catch { /* unread badge is non-blocking */ } }, [me]);
  useEffect(() => { void loadListings(); void loadStories(); }, [loadListings, loadStories]);
  useEffect(() => { void loadUnread(); const timer = window.setInterval(() => void loadUnread(), 9000); return () => window.clearInterval(timer); }, [loadUnread]);
  useEffect(() => { document.documentElement.classList.toggle('dark', dark); localStorage.setItem('peida-theme', dark ? 'dark' : 'light'); }, [dark]);
  useEffect(() => { localStorage.setItem('peida-saved', JSON.stringify(saved)); }, [saved]);
  useEffect(() => { if (me) localStorage.setItem(SESSION_KEY, JSON.stringify(me)); else localStorage.removeItem(SESSION_KEY); }, [me]);
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(''), 3300); return () => window.clearTimeout(timer); }, [toast]);
  const go = (next: Page) => { setPage(next); history.pushState({}, '', next === 'admin' ? '/admin' : '/'); window.scrollTo({ top: 0 }); };
  const toggleSaved = (id: number) => setSaved((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]);
  const visible = useMemo(() => ads.filter((ad) => { const text = (ad.title + ad.description + ad.category).toLowerCase(); return (!query || text.includes(query.toLowerCase())) && categoryMatches(filters.category, ad.category) && (!filters.province || ad.province === filters.province) && (!filters.county || ad.county === filters.county || ad.city === filters.county) && (!filters.village || ad.village === filters.village) && (!filters.minPrice || ad.price >= Number(filters.minPrice)) && (!filters.maxPrice || ad.price <= Number(filters.maxPrice)); }).sort((a, b) => filters.sort === 'cheap' ? a.price - b.price : filters.sort === 'expensive' ? b.price - a.price : filters.sort === 'popular' ? b.views - a.views : b.id - a.id), [ads, query, filters]);
  const openAd = async (ad: Ad) => { setSelected(ad); setComments([]); go('detail'); try { const response = await fetch('/api/listings/' + ad.id); if (!response.ok) throw new Error(); const result = await response.json() as { listing: Ad; comments: Comment[] }; setSelected(result.listing); setComments(result.comments || []); setAds((items) => items.map((item) => item.id === ad.id ? result.listing : item)); } catch { notify('جزئیات کامل آگهی دریافت نشد.'); } };
  const openStory = (index: number) => { setStoryIndex(index); const story = stories[index]; if (story) void fetch('/api/stories/' + story.id + '/view', { method: 'POST' }); };
  const label = filters.village || filters.county || filters.province || 'همه ایران';
  if (page === 'admin') return <AdminScreen leave={() => go('home')} dark={dark} toggleDark={() => setDark(!dark)} notify={notify} />;
  if (!me) return <Onboarding onDone={(user) => { setMe(user); go('home'); }} />;
  const common = { openAd, saved, toggleSaved };
  return <div className="min-h-screen bg-[#f4f6f5] pb-24 text-zinc-800 dark:bg-[#0e1513] dark:text-zinc-100">
    <header className="sticky top-0 z-40 border-b border-zinc-200/70 bg-white/95 backdrop-blur dark:border-white/10 dark:bg-[#131c19]/95"><div className="mx-auto flex h-17 w-full max-w-7xl items-center gap-2 px-3 sm:gap-3 sm:px-6 lg:px-8"><button data-testid="city-selector" onClick={() => setCityOpen(true)} className="flex min-h-10 shrink-0 flex-col items-center justify-center rounded-2xl bg-emerald-50 px-2.5 text-[#0b7f47] dark:bg-emerald-950/30"><span className="flex items-center gap-1 text-[11px] font-black"><MapPin size={13} /><span className="max-w-16 truncate sm:max-w-28">{label}</span><ChevronDown size={11} /></span><small className="mt-1 text-[8px] font-bold">انتخاب شهر</small></button><label className="flex h-9 min-w-0 flex-1 items-center gap-2 rounded-full border border-zinc-200 bg-zinc-50 px-3 focus-within:border-emerald-400 dark:border-white/10 dark:bg-white/5"><Search size={15} className="shrink-0 text-zinc-400" /><input data-testid="search-input" value={query} onFocus={() => page !== 'browse' && go('browse')} onChange={(e) => setQuery(e.target.value)} className="w-full min-w-0 bg-transparent text-[11px] outline-none placeholder:text-zinc-400 sm:text-xs" placeholder="جستجو در پیدا ..." /></label><button data-testid="brand-home" onClick={() => go('home')} aria-label="پیدا" className="shrink-0"><PeidaLogo size={29} /></button></div></header>
    <main className="mx-auto w-full max-w-7xl px-3 py-3 sm:px-6 lg:px-8">
      {page === 'home' && <HomeScreen ads={visible} stories={stories} loading={loading} failed={failed} locationLabel={label} selectCategory={(category) => { setFilters({ ...filters, category }); go('browse'); }} openFilters={() => setFilterOpen(true)} openCity={() => setCityOpen(true)} openCategories={() => go('categories')} createStory={() => setComposer(true)} openStory={openStory} seeAll={() => go('browse')} openSpecial={() => { setFilters({ ...filters, sort: 'newest' }); go('browse'); }} {...common} />}
      {page === 'categories' && <CategoriesScreen select={(category) => { setFilters({ ...filters, category }); go('browse'); }} />}
      {page === 'browse' && <BrowseScreen ads={visible} loading={loading} filters={filters} setFilters={setFilters} openAd={openAd} openFilters={() => setFilterOpen(true)} openCity={() => setCityOpen(true)} locationLabel={label} saved={saved} toggleSaved={toggleSaved} />}
      {page === 'saved' && <SavedScreen ads={ads.filter((ad) => saved.includes(ad.id))} openAd={openAd} saved={saved} toggleSaved={toggleSaved} />}
      {page === 'detail' && selected && <DetailScreen ad={selected} me={me} comments={comments} back={() => go('browse')} edit={() => { setEditing(selected); go('post'); }} notify={notify} openChat={(id) => { setPendingChat(id); go('messages'); }} reloadComments={async () => { const r = await fetch('/api/listings/' + selected.id); if (r.ok) { const d = await r.json() as { comments: Comment[] }; setComments(d.comments || []); } }} />}
      {page === 'post' && <PostScreen me={me} editing={editing} done={async () => { setEditing(null); await loadListings(); go('profile'); }} cancel={() => { setEditing(null); go('home'); }} notify={notify} />}
      {page === 'profile' && <ProfileScreen me={me} setMe={setMe} ads={ads.filter((ad) => ad.user_id === me.id)} openAd={openAd} edit={(ad) => { setEditing(ad); go('post'); }} manage={() => go('manage')} saved={() => go('saved')} post={() => { setEditing(null); go('post'); }} signOut={() => { setMe(null); go('home'); }} dark={dark} toggleDark={() => setDark(!dark)} notify={notify} />}
      {page === 'manage' && <ManageScreen ads={ads.filter((ad) => ad.user_id === me.id)} me={me} reload={loadListings} edit={(ad) => { setEditing(ad); go('post'); }} back={() => go('profile')} notify={notify} />}
      {page === 'messages' && <MessagesScreen me={me} notify={notify} initial={pendingChat} clearInitial={() => { setPendingChat(null); void loadUnread(); }} />}
    </main>
    <footer className="mx-auto mb-2 max-w-7xl px-5 text-center text-[10px] text-zinc-400"><button data-testid="footer-admin" onClick={() => go('admin')} className="hover:text-[#12a05c]">ورود مدیریت</button></footer>
    <nav className="fixed inset-x-0 bottom-0 z-40 border-t border-zinc-200 bg-white px-2 pb-[env(safe-area-inset-bottom)] pt-1.5 shadow-[0_-4px_18px_rgba(0,0,0,.06)] dark:border-white/10 dark:bg-[#131c19]"><div className="mx-auto flex max-w-md items-end justify-between"><NavItem id="nav-home" title="خانه" active={page === 'home'} icon={<Home size={20} />} onClick={() => go('home')} /><NavItem id="nav-categories" title="دسته‌بندی‌ها" active={page === 'categories'} icon={<LayoutGrid size={20} />} onClick={() => go('categories')} /><button data-testid="nav-post" onClick={() => { setEditing(null); go('post'); }} className="-mt-6 flex w-18 flex-col items-center"><span className="grid size-14 place-items-center rounded-full border-4 border-white bg-[#12a05c] text-white shadow-lg dark:border-[#131c19]"><Plus size={24} /></span><b className="mt-0.5 text-[9px] text-[#12a05c]">ثبت آگهی</b></button><NavItem id="nav-messages" title="پیام‌ها" active={page === 'messages'} icon={<span className="relative"><MessageCircle size={20} />{unread > 0 && <i data-testid="unread-message-badge" className="absolute -right-2 -top-2 grid min-w-4 place-items-center rounded-full bg-rose-500 px-1 text-[8px] not-italic text-white">{unread > 99 ? '۹۹+' : fnum(unread)}</i>}</span>} onClick={() => { go('messages'); void loadUnread(); }} /><NavItem id="nav-profile" title="پروفایل" active={page === 'profile'} icon={<UserRound size={20} />} onClick={() => go('profile')} /></div></nav>
    {cityOpen && <LocationSheet value={filters} setValue={setFilters} close={() => setCityOpen(false)} />}{filterOpen && <FilterSheet value={filters} change={setFilters} close={() => setFilterOpen(false)} />}{composer && <StoryComposer me={me} close={() => setComposer(false)} refresh={loadStories} notify={notify} />}{storyIndex !== null && stories[storyIndex] && <StoryViewer story={stories[storyIndex]} me={me} close={() => setStoryIndex(null)} notify={notify} refresh={loadStories} move={(direction) => setStoryIndex((current) => current === null ? 0 : (current + direction + stories.length) % stories.length)} />}{toast && <div data-testid="toast" className="fixed bottom-24 left-1/2 z-[80] w-[calc(100%-2rem)] max-w-md -translate-x-1/2 rounded-2xl bg-zinc-900 px-4 py-3 text-center text-xs leading-6 text-white shadow-2xl">{toast}</div>}
  </div>;
}
function NavItem({ id, title, icon, active, onClick }: { id: string; title: string; icon: ReactNode; active: boolean; onClick: () => void }) { return <button data-testid={id} onClick={onClick} className={'flex min-h-12 w-16 flex-col items-center justify-center gap-0.5 text-[9px] font-bold ' + (active ? 'text-[#12a05c]' : 'text-zinc-500')} >{icon}{title}</button>; }

function HomeScreen({ ads, stories, loading, failed, locationLabel, selectCategory, openFilters, openCity, openCategories, createStory, openStory, seeAll, openSpecial, openAd, saved, toggleSaved }: { ads: Ad[]; stories: StoryItem[]; loading: boolean; failed: boolean; locationLabel: string; selectCategory: (value: string) => void; openFilters: () => void; openCity: () => void; openCategories: () => void; createStory: () => void; openStory: (index: number) => void; seeAll: () => void; openSpecial: () => void; openAd: (ad: Ad) => void; saved: number[]; toggleSaved: (id: number) => void }) {
  const specials = ads.filter((item) => item.isSpecial);
  return <><section className="mb-3 -mx-1 flex gap-3 overflow-x-auto px-1 pb-1 scrollless"><button data-testid="story-create-ring" onClick={createStory} className="w-16 shrink-0"><span className="mx-auto grid size-15 place-items-center rounded-full border-2 border-dashed border-emerald-400 bg-emerald-50 text-[#12a05c] dark:bg-emerald-950/30"><Plus size={22} /></span><b className="mt-1 block truncate text-[9px]">افزودن استوری</b></button>{stories.map((story, index) => <button data-testid={'story-' + story.id} key={story.id} onClick={() => openStory(index)} className="w-16 shrink-0"><span className="story-ring mx-auto block size-15 rounded-full p-[2px]"><img src={story.seller_avatar || story.image} alt="" className="size-full rounded-full border-2 border-white object-cover dark:border-[#0e1513]" /></span><b className="mt-1 block truncate text-[9px]">{story.seller_name}</b></button>)}</section>
    <section className="relative mb-4 overflow-hidden rounded-2xl bg-gradient-to-l from-[#087740] via-[#12a05c] to-[#35bd78] p-4 text-white"><Crown className="absolute -bottom-5 -left-3 size-28 opacity-10" /><div className="relative flex items-center justify-between gap-3"><div><h2 className="text-xl font-black">آگهی ویژه</h2><p className="mt-1 text-[11px] font-bold text-emerald-50">آگهی شما ۳۰ روز در جایگاه اول دیده می‌شود.</p><button data-testid="open-special-listings" onClick={openSpecial} className="mt-3 min-h-9 rounded-xl bg-white px-4 text-[11px] font-black text-[#0b7f47]">مشاهده آگهی‌های ویژه</button></div><Crown className="size-16 text-amber-200" /></div></section>
    {specials.length > 0 && <section className="mb-4"><div className="mb-2 flex items-center justify-between"><b className="text-[13px] font-black">ویژه‌های امروز</b><span className="text-[10px] text-[#12a05c]">برجسته‌شده</span></div><div className="-mx-1 flex gap-2 overflow-x-auto px-1 pb-1 scrollless">{specials.slice(0, 5).map((ad) => <AdCard key={ad.id} ad={ad} openAd={openAd} saved={saved.includes(ad.id)} toggleSaved={toggleSaved} />)}</div></section>}
    <section className="mb-4 grid grid-cols-5 gap-1.5 sm:gap-3">{CATEGORIES.map((item) => <button data-testid={'category-' + item.key} key={item.key} onClick={() => selectCategory(item.key)} className="soft-card rounded-xl bg-white p-1.5 dark:bg-[#17211e]"><CategoryArt item={item} className="h-10 w-full rounded-lg sm:h-16" /><b className="mt-1 block truncate text-center text-[9px] sm:text-[11px]">{item.key}</b></button>)}</section>
    <section className="soft-card mb-4 flex divide-x divide-x-reverse divide-zinc-100 rounded-xl bg-white text-[11px] font-bold dark:divide-white/10 dark:bg-[#17211e]"><button data-testid="open-advanced-filters" onClick={openFilters} className="flex min-h-11 flex-1 items-center justify-center gap-1"><SlidersHorizontal size={14} />فیلتر</button><button data-testid="open-categories" onClick={openCategories} className="flex min-h-11 flex-1 items-center justify-center gap-1"><LayoutGrid size={14} />دسته‌بندی‌ها</button><button data-testid="home-city" onClick={openCity} className="flex min-h-11 min-w-0 flex-1 items-center justify-center gap-1"><MapPin size={14} className="text-[#12a05c]" /><span className="max-w-20 truncate">{locationLabel}</span><ChevronDown size={12} /></button></section>
    <section><div className="mb-2 flex items-center justify-between"><h2 className="text-[13px] font-black">آگهی‌های نزدیک شما</h2><button data-testid="see-all-listings" onClick={seeAll} className="flex items-center text-[11px] font-bold text-[#12a05c]">مشاهده همه<ChevronLeft size={14} /></button></div>{loading && <div className="flex gap-2 overflow-hidden">{[1, 2, 3, 4].map((item) => <div key={item} className="h-44 w-36 shrink-0 animate-pulse rounded-2xl bg-white dark:bg-[#17211e]" />)}</div>}{failed && !loading && <div data-testid="listings-error" className="rounded-2xl bg-white p-6 text-center text-sm dark:bg-[#17211e]">آگهی‌ها دریافت نشدند.</div>}{!loading && !failed && !ads.length && <div data-testid="empty-home" className="rounded-2xl bg-white p-8 text-center text-sm text-zinc-500 dark:bg-[#17211e]">هنوز آگهی‌ای در این موقعیت ثبت نشده است.</div>}{ads.length > 0 && <div className="-mx-1 flex gap-2 overflow-x-auto px-1 pb-2 scrollless">{ads.slice(0, 14).map((ad) => <AdCard key={ad.id} ad={ad} openAd={openAd} saved={saved.includes(ad.id)} toggleSaved={toggleSaved} />)}</div>}</section></>;
}
function AdCard({ ad, openAd, saved, toggleSaved }: { ad: Ad; openAd: (ad: Ad) => void; saved: boolean; toggleSaved: (id: number) => void }) { return <div className="ad-card soft-card relative w-36 shrink-0 overflow-hidden rounded-2xl bg-white text-right dark:bg-[#17211e]"><button data-testid={'listing-' + ad.id} onClick={() => openAd(ad)} className="block w-full text-right"><div className="relative overflow-hidden"><img src={ad.images[0] || PLACEHOLDER_IMAGE} alt={ad.title} className="h-24 w-full object-cover" />{ad.isSpecial && <span className="absolute right-1.5 top-1.5 flex items-center gap-0.5 rounded-lg bg-amber-400 px-1.5 py-0.5 text-[8px] font-black text-amber-950"><Crown size={10} />ویژه</span>}<span className="absolute bottom-1.5 right-1.5 max-w-[92%] truncate rounded-lg bg-[#12a05c] px-1.5 py-0.5 text-[9px] font-black text-white">{toman(ad.price)}</span></div><div className="p-2"><h3 className="line-clamp-1 text-[11px] font-bold">{ad.title}</h3><p className="mt-1 truncate text-[9px] text-zinc-400">{ad.village || ad.county || ad.city}</p><p className="mt-1 text-[9px] text-zinc-400"><Eye className="inline" size={10} /> {fnum(ad.views)} بازدید</p></div></button><button data-testid={'save-' + ad.id} onClick={() => toggleSaved(ad.id)} className="absolute left-1.5 top-1.5 grid size-7 place-items-center rounded-full bg-white/90 text-zinc-500"><Heart size={14} className={saved ? 'fill-[#12a05c] text-[#12a05c]' : ''} /></button></div>; }
function CategoriesScreen({ select }: { select: (category: string) => void }) { return <section><h1 className="mb-3 text-lg font-black">دسته‌بندی‌ها</h1><div className="grid grid-cols-2 gap-2 sm:grid-cols-4 lg:grid-cols-5">{CATEGORIES.map((item) => <button data-testid={'all-category-' + item.key} key={item.key} onClick={() => select(item.key)} className="soft-card overflow-hidden rounded-2xl bg-white dark:bg-[#17211e]"><CategoryArt item={item} className="h-24 w-full" /><b className="block p-2 text-center text-xs">{item.key}</b></button>)}</div></section>; }
function BrowseScreen({ ads, loading, filters, setFilters, openAd, openFilters, openCity, locationLabel, saved, toggleSaved }: { ads: Ad[]; loading: boolean; filters: Filters; setFilters: (f: Filters) => void; openAd: (ad: Ad) => void; openFilters: () => void; openCity: () => void; locationLabel: string; saved: number[]; toggleSaved: (id: number) => void }) { return <><div className="mb-3 flex items-center justify-between gap-2"><h1 className="text-lg font-black">{filters.category === 'همه' ? 'همه آگهی‌ها' : filters.category}</h1><div className="flex gap-2"><button data-testid="browse-city" onClick={openCity} className="flex min-h-10 items-center gap-1 rounded-xl bg-white px-3 text-[11px] dark:bg-[#17211e]"><MapPin size={14} />{locationLabel}</button><button data-testid="browse-filter" onClick={openFilters} className="flex min-h-10 items-center gap-1 rounded-xl bg-white px-3 text-[11px] dark:bg-[#17211e]"><SlidersHorizontal size={14} />فیلتر</button></div></div><div className="-mx-1 mb-3 flex gap-2 overflow-x-auto px-1 pb-1 scrollless">{['همه', ...categoryKeys].map((category) => <button data-testid={'filter-category-' + category} key={category} onClick={() => setFilters({ ...filters, category })} className={'min-h-9 shrink-0 rounded-full px-3 text-[11px] font-bold ' + (filters.category === category ? 'bg-[#12a05c] text-white' : 'bg-white dark:bg-[#17211e]')}>{category}</button>)}</div>{loading ? <div className="grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-5">{[1,2,3,4,5].map((i) => <div key={i} className="h-48 animate-pulse rounded-2xl bg-white dark:bg-[#17211e]" />)}</div> : ads.length ? <div className="grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-5">{ads.map((ad) => <div key={ad.id} className="w-full"><AdCard ad={ad} openAd={openAd} saved={saved.includes(ad.id)} toggleSaved={toggleSaved} /></div>)}</div> : <div data-testid="empty-listings" className="rounded-3xl bg-white px-4 py-14 text-center dark:bg-[#17211e]"><Search className="mx-auto text-zinc-300" /><b className="mt-3 block">آگهی هم‌خوانی پیدا نشد</b><button data-testid="empty-filter-button" onClick={openFilters} className="mt-4 text-sm font-bold text-[#12a05c]">ویرایش فیلترها</button></div>}</>; }
function SavedScreen({ ads, openAd, saved, toggleSaved }: { ads: Ad[]; openAd: (ad: Ad) => void; saved: number[]; toggleSaved: (id: number) => void }) { return <section><div className="mb-4"><h1 className="text-lg font-black">آگهی‌های ذخیره‌شده</h1><p className="mt-1 text-xs text-zinc-500">آگهی‌هایی که برای دیدن بعدی نگه داشته‌اید.</p></div>{ads.length ? <div className="grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-5">{ads.map((ad) => <AdCard key={ad.id} ad={ad} openAd={openAd} saved={saved.includes(ad.id)} toggleSaved={toggleSaved} />)}</div> : <div data-testid="saved-empty" className="rounded-3xl bg-white p-10 text-center dark:bg-[#17211e]"><Heart className="mx-auto text-zinc-300" /><b className="mt-3 block">هنوز آگهی ذخیره‌شده‌ای ندارید</b><p className="mt-2 text-xs text-zinc-500">روی قلب هر آگهی بزنید تا این‌جا بماند.</p></div>}</section>; }

function DetailScreen({ ad, me, comments, back, edit, notify, reloadComments, openChat }: { ad: Ad; me: User; comments: Comment[]; back: () => void; edit: () => void; notify: (t: string) => void; reloadComments: () => Promise<void>; openChat: (id: number) => void }) {
  const [photo, setPhoto] = useState(0); const [message, setMessage] = useState(''); const [comment, setComment] = useState(''); const [sending, setSending] = useState(false); const mine = ad.user_id === me.id;
  const send = async () => { if (mine) return notify('این آگهی متعلق به خودتان است.'); const body = message.trim() || 'سلام، این آگهی هنوز موجود است؟'; setSending(true); try { const response = await fetch('/api/conversations', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ listingId: ad.id, buyerId: me.id, sellerId: ad.user_id, body }) }); const data = await response.json() as { conversationId?: number }; if (!response.ok || !data.conversationId) throw new Error(); setMessage(''); openChat(data.conversationId); } catch { notify('ارسال پیام انجام نشد؛ دوباره تلاش کنید.'); } finally { setSending(false); } };
  const addComment = async () => { if (!comment.trim()) return notify('نظر خود را بنویسید.'); try { const response = await fetch('/api/listings/' + ad.id + '/comments', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ body: comment, author: me.name }) }); if (!response.ok) throw new Error(); setComment(''); await reloadComments(); notify('نظر شما ثبت شد.'); } catch { notify('ثبت نظر انجام نشد.'); } };
  const phone = (ad.seller_phone || '').replace(/\D/g, ''); const handle = (v?: string) => (v || '').replace('@', '').trim(); const socials = [{ name: 'واتساپ', url: 'https://wa.me/98' + (ad.seller_whatsapp || phone).replace(/^0/, ''), color: 'bg-emerald-500' }, { name: 'تلگرام', url: handle(ad.seller_telegram) ? 'https://t.me/' + handle(ad.seller_telegram) : 'https://t.me', color: 'bg-sky-500' }, { name: 'اینستاگرام', url: handle(ad.seller_instagram) ? 'https://instagram.com/' + handle(ad.seller_instagram) : 'https://instagram.com', color: 'bg-rose-500' }, { name: 'ایتا', url: handle(ad.seller_eitaa) ? 'https://eitaa.com/' + handle(ad.seller_eitaa) : 'https://eitaa.com', color: 'bg-amber-500' }, { name: 'روبیکا', url: handle(ad.seller_rubika) ? 'https://rubika.ir/' + handle(ad.seller_rubika) : 'https://rubika.ir', color: 'bg-indigo-500' }];
  return <div><button data-testid="detail-back" onClick={back} className="mb-3 flex min-h-10 items-center gap-1 text-xs text-zinc-500"><ChevronRight size={17} />بازگشت</button><div className="grid gap-4 lg:grid-cols-[minmax(0,1.25fr)_360px]"><section><div className="relative overflow-hidden rounded-3xl bg-zinc-200 dark:bg-zinc-800"><img src={ad.images[photo] || PLACEHOLDER_IMAGE} alt={ad.title} className="aspect-[1.15] w-full object-cover" />{ad.images.length > 1 && <><button data-testid="previous-photo" onClick={() => setPhoto((photo - 1 + ad.images.length) % ad.images.length)} className="absolute right-3 top-1/2 grid size-10 -translate-y-1/2 place-items-center rounded-full bg-white/90"><ChevronRight /></button><button data-testid="next-photo" onClick={() => setPhoto((photo + 1) % ad.images.length)} className="absolute left-3 top-1/2 grid size-10 -translate-y-1/2 place-items-center rounded-full bg-white/90"><ChevronLeft /></button></>}<span data-testid="detail-price" className="absolute bottom-3 right-3 rounded-xl bg-[#12a05c] px-3 py-2 text-sm font-black text-white">{toman(ad.price)}</span></div>{ad.images.length > 1 && <div className="mt-2 flex gap-2 overflow-x-auto scrollless">{ad.images.map((image, i) => <button data-testid={'thumb-' + i} key={image} onClick={() => setPhoto(i)} className={'size-14 shrink-0 overflow-hidden rounded-xl border-2 ' + (photo === i ? 'border-[#12a05c]' : 'border-transparent')}><img src={image} alt="" className="size-full object-cover" /></button>)}</div>}<div className="mt-3 rounded-3xl bg-white p-5 dark:bg-[#17211e]"><div className="flex gap-2">{ad.isSpecial && <span className="rounded-lg bg-amber-100 px-2 py-1 text-[10px] font-black text-amber-800"><Crown className="inline" size={12} /> آگهی ویژه</span>}<h1 data-testid="detail-title" className="text-lg font-black">{ad.title}</h1></div><p className="mt-3 text-[11px] text-zinc-500"><MapPin className="inline" size={14} /> {[ad.province, ad.county || ad.city, ad.village].filter(Boolean).join(' · ')}<span className="mx-2">|</span><Eye className="inline" size={14} /> {fnum(ad.views)} بازدید</p><hr className="my-4 border-zinc-100 dark:border-white/10" /><b className="text-sm">توضیحات آگهی</b><p className="mt-2 text-sm leading-7 text-zinc-600 dark:text-zinc-300">{ad.description}</p></div></section><aside className="space-y-3"><div className="rounded-3xl bg-white p-5 dark:bg-[#17211e]"><div className="flex items-center gap-3"><span className="grid size-12 shrink-0 place-items-center overflow-hidden rounded-full bg-emerald-50 font-black text-[#12a05c]">{ad.seller_avatar ? <img src={ad.seller_avatar} alt="" className="size-full object-cover" /> : ad.seller_name.slice(0,1)}</span><div className="min-w-0"><b className="block truncate">{ad.seller_name}</b><p className="text-[11px] text-zinc-500">آگهی‌دهنده در پیدا</p></div></div><div className="mt-4 rounded-2xl bg-emerald-50 p-3 dark:bg-emerald-950/20"><p className="text-[11px] text-zinc-500">شماره تماس آگهی‌دهنده</p><a data-testid="seller-phone" dir="ltr" href={'tel:' + ad.seller_phone} className="mt-1 block text-right text-base font-black text-[#0b7f47]">{ad.seller_phone}</a></div><div className="mt-3 grid grid-cols-2 gap-2"><a data-testid="call-seller" href={'tel:' + ad.seller_phone} className="flex min-h-12 items-center justify-center gap-1 rounded-xl bg-[#12a05c] text-sm font-bold text-white"><Phone size={17} />تماس</a><button data-testid="message-seller" disabled={sending} onClick={() => void send()} className="flex min-h-12 items-center justify-center gap-1 rounded-xl bg-emerald-50 text-sm font-bold text-[#0b7f47] disabled:opacity-60 dark:bg-emerald-950/30"><MessageCircle size={17} />پیام</button></div><div className="mt-2 flex gap-2"><input data-testid="quick-message" className="input min-w-0 flex-1" value={message} onChange={(e) => setMessage(e.target.value)} placeholder="پیام به آگهی‌دهنده..." /><button data-testid="quick-message-send" onClick={() => void send()} className="grid size-11 shrink-0 place-items-center rounded-xl bg-[#0b7f47] text-white"><Send size={16} /></button></div><p className="mt-4 text-[11px] font-bold text-zinc-500">شبکه‌های اجتماعی آگهی‌دهنده</p><div className="mt-2 grid grid-cols-5 gap-1">{socials.map((social) => <a data-testid={'social-' + social.name} key={social.name} href={social.url} target="_blank" rel="noreferrer" className={'grid min-h-10 place-items-center rounded-lg px-1 text-center text-[8px] font-bold text-white ' + social.color}>{social.name}</a>)}</div>{mine && <button data-testid="manage-current-listing" onClick={edit} className="mt-3 min-h-11 w-full rounded-xl border border-emerald-200 text-xs font-bold text-[#0b7f47]"><Edit3 className="inline" size={15} />ویرایش این آگهی</button>}</div><button data-testid="report-listing" onClick={() => notify('گزارش شما ثبت شد و بررسی می‌شود.')} className="min-h-11 w-full rounded-xl border border-zinc-200 text-xs text-zinc-500 dark:border-white/10"><Flag className="inline" size={14} />گزارش آگهی</button></aside></div><section className="mt-4 max-w-3xl rounded-3xl bg-white p-5 dark:bg-[#17211e]"><b className="text-sm">نظرها و پرسش‌ها</b><div className="mt-3 flex gap-2"><input data-testid="comment-input" className="input min-w-0 flex-1" value={comment} onChange={(e) => setComment(e.target.value)} placeholder="نظر خود را بنویسید..." /><button data-testid="submit-comment" onClick={() => void addComment()} className="grid size-11 shrink-0 place-items-center rounded-xl bg-[#12a05c] text-white"><Send size={17} /></button></div><div className="mt-4 space-y-2">{comments.length ? comments.map((item) => <div data-testid={'comment-' + item.id} key={item.id} className="rounded-2xl bg-zinc-50 p-3 text-sm dark:bg-white/5"><b className="text-xs text-[#0b7f47]">{item.author}</b><p className="mt-1 leading-6">{item.body}</p></div>) : <p data-testid="empty-comments" className="text-xs text-zinc-500">هنوز نظری ثبت نشده است؛ اولین نفر باشید.</p>}</div></section></div>;
}

function PostScreen({ me, editing, done, cancel, notify }: { me: User; editing: Ad | null; done: () => Promise<void>; cancel: () => void; notify: (t: string) => void }) { const [form, setForm] = useState({ title: editing?.title || '', description: editing?.description || '', category: editing?.category || CATEGORIES[0].key, province: editing?.province || me.province || '', county: editing?.county || editing?.city || me.county || '', village: editing?.village || '', price: editing ? String(editing.price) : '', isSpecial: Boolean(editing?.isSpecial) }); const [files, setFiles] = useState<File[]>([]); const [kept, setKept] = useState(editing?.images || []); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const submit = async (event: FormEvent) => { event.preventDefault(); if (!form.title.trim() || !form.description.trim() || !form.province || !form.county || !form.price) return setError('عنوان، توضیحات، قیمت، استان و شهرستان را کامل کنید.'); if (!kept.length && !files.length) return setError('حداقل یک تصویر برای آگهی انتخاب کنید.'); setBusy(true); setError(''); try { const uploaded = await uploadImages(files); const response = await fetch(editing ? '/api/listings/' + editing.id : '/api/listings', { method: editing ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ...form, price: Number(form.price), city: form.county, images: [...kept, ...uploaded], userId: me.id }) }); if (!response.ok) throw new Error('ذخیره آگهی انجام نشد؛ دوباره تلاش کنید.'); notify(editing ? 'تغییرات آگهی ذخیره شد.' : form.isSpecial ? 'آگهی ویژه شما ثبت شد.' : 'آگهی شما ثبت شد.'); await done(); } catch (problem) { setError(problem instanceof Error ? problem.message : 'ذخیره آگهی انجام نشد.'); } finally { setBusy(false); } }; return <section className="mx-auto max-w-3xl"><div className="mb-3 flex items-start justify-between"><div><h1 className="text-lg font-black">{editing ? 'ویرایش آگهی' : 'ثبت آگهی'}</h1><p className="mt-1 text-[11px] text-zinc-500">با عکس و موقعیت دقیق، سریع‌تر خریدار پیدا می‌کنید.</p></div><button data-testid="cancel-edit" onClick={cancel} className="min-h-10 text-xs text-zinc-500">انصراف</button></div><form onSubmit={submit} className="space-y-4 rounded-3xl bg-white p-5 dark:bg-[#17211e]"><Field title="عنوان آگهی"><input data-testid="post-title" className="input" value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} placeholder="مثلاً دوچرخه کوهستان سالم" /></Field><div className="grid gap-3 sm:grid-cols-2"><Field title="دسته‌بندی"><select data-testid="post-category" className="input" value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })}>{categoryKeys.map((item) => <option key={item}>{item}</option>)}</select></Field><Field title="قیمت (تومان)"><input data-testid="post-price" className="input" inputMode="numeric" value={form.price} onChange={(e) => setForm({ ...form, price: e.target.value.replace(/\D/g, '') })} /></Field></div><LocationInputs value={form} onChange={(place) => setForm({ ...form, ...place })} ids={['post-province','post-county','post-village']} /><Field title="توضیحات"><textarea data-testid="post-description" className="input min-h-28 resize-none" value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} placeholder="وضعیت کالا و جزئیات دیگر..." /></Field><label data-testid="make-special" className="flex cursor-pointer items-center gap-3 rounded-2xl border border-amber-200 bg-amber-50 p-3 dark:border-amber-900/60 dark:bg-amber-950/20"><input type="checkbox" checked={form.isSpecial} onChange={(e) => setForm({ ...form, isSpecial: e.target.checked })} className="size-4 accent-[#12a05c]" /><Crown className="text-amber-500" size={20} /><span><b className="block text-sm">فعال‌سازی آگهی ویژه</b><small className="text-[11px] text-zinc-500">نمایش برجسته در صفحه اصلی تا ۳۰ روز</small></span></label><Field title="تصاویر آگهی"><ImagePicker files={files} setFiles={setFiles} testId="post-images" existing={kept} removeExisting={(image) => setKept(kept.filter((item) => item !== image))} /></Field>{error && <p data-testid="post-error" className="rounded-xl bg-rose-50 p-3 text-xs font-bold text-rose-600">{error}</p>}<button data-testid="submit-listing" disabled={busy} className="min-h-12 w-full rounded-xl bg-[#12a05c] text-sm font-black text-white disabled:opacity-60">{busy ? 'در حال ثبت...' : editing ? 'ذخیره تغییرات' : form.isSpecial ? 'ثبت آگهی ویژه' : 'ثبت آگهی'}</button></form></section>; }

function ProfileScreen({ me, setMe, ads, openAd, edit, manage, saved, post, signOut, dark, toggleDark, notify }: { me: User; setMe: (u: User) => void; ads: Ad[]; openAd: (a: Ad) => void; edit: (a: Ad) => void; manage: () => void; saved: () => void; post: () => void; signOut: () => void; dark: boolean; toggleDark: () => void; notify: (t: string) => void }) { const [open, setOpen] = useState(false); const [draft, setDraft] = useState(me); const [busy, setBusy] = useState(false); const avatar = async (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; setBusy(true); try { setDraft({ ...draft, avatar: await uploadImage(file) }); notify('عکس انتخاب شد؛ تغییرات را ذخیره کنید.'); } catch (error) { notify(error instanceof Error ? error.message : 'بارگذاری تصویر انجام نشد.'); } finally { setBusy(false); event.target.value = ''; } }; const save = async () => { try { const response = await fetch('/api/users/' + me.id, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(draft) }); if (!response.ok) throw new Error(); const data = await response.json() as { user: User }; setMe(data.user); setOpen(false); notify('پروفایل ذخیره شد.'); } catch { notify('ذخیره پروفایل انجام نشد.'); } }; return <section className="mx-auto max-w-5xl"><div className="rounded-3xl bg-gradient-to-l from-[#0b7f47] to-[#19b26a] p-5 text-white"><div className="flex flex-col items-center gap-3 text-center sm:flex-row sm:text-right"><span className="grid size-16 place-items-center overflow-hidden rounded-full border-2 border-white/70 bg-white/15 text-xl font-black">{me.avatar ? <img src={me.avatar} alt="" className="size-full object-cover" /> : me.name.slice(0,1)}</span><div className="min-w-0 flex-1"><h1 className="truncate text-lg font-black">{me.name}</h1><p dir="ltr" className="mt-1 text-right text-[11px] text-emerald-50">{me.phone}</p><p className="mt-1 text-[11px] text-emerald-50">{[me.province, me.county || me.city, me.village].filter(Boolean).join(' · ')}</p></div><button data-testid="profile-manage-ads" onClick={manage} className="min-h-10 rounded-xl bg-white/15 px-3 text-xs font-bold">مدیریت آگهی‌ها</button><button data-testid="edit-profile" onClick={() => { setDraft(me); setOpen(!open); }} className="min-h-10 rounded-xl bg-white px-3 text-xs font-black text-[#0b7f47]">ویرایش پروفایل</button></div></div><div className="mt-3 flex flex-wrap gap-2"><button data-testid="profile-saved" onClick={saved} className="flex min-h-10 items-center gap-2 rounded-xl bg-white px-3 text-[11px] font-bold dark:bg-[#17211e]"><Heart size={15} className="text-[#12a05c]" />آگهی‌های ذخیره‌شده</button><button data-testid="theme-toggle" onClick={toggleDark} className="flex min-h-10 items-center gap-2 rounded-xl bg-white px-3 text-[11px] font-bold dark:bg-[#17211e]">{dark ? <Sun size={15} /> : <Moon size={15} />}{dark ? 'حالت روشن' : 'حالت تیره'}</button><button data-testid="sign-out" onClick={signOut} className="flex min-h-10 items-center gap-2 rounded-xl bg-white px-3 text-[11px] font-bold text-rose-600 dark:bg-[#17211e]"><LogOut size={15} />خروج</button></div>{open && <div className="mt-4 space-y-4 rounded-3xl bg-white p-5 dark:bg-[#17211e]"><div className="grid gap-3 sm:grid-cols-2"><Field title="نام"><input data-testid="profile-name" className="input" value={draft.name} onChange={(e) => setDraft({ ...draft, name: e.target.value })} /></Field><Field title="سن"><input data-testid="profile-age" className="input" inputMode="numeric" value={draft.age || ''} onChange={(e) => setDraft({ ...draft, age: e.target.value.replace(/\D/g, '') })} /></Field></div><Field title="عکس پروفایل"><label data-testid="profile-avatar" className="flex min-h-12 cursor-pointer items-center justify-center gap-2 rounded-xl border-2 border-dashed border-emerald-300 text-xs font-bold text-[#0b7f47]"><ImagePlus size={16} />{busy ? 'در حال بارگذاری...' : 'انتخاب عکس پروفایل'}<input type="file" accept="image/*" className="hidden" onChange={(e) => void avatar(e)} /></label></Field><LocationInputs value={{ province: draft.province || '', county: draft.county || draft.city || '', village: draft.village || '' }} onChange={(place) => setDraft({ ...draft, ...place, city: place.county })} ids={['profile-province','profile-county','profile-village']} /><div className="grid gap-3 sm:grid-cols-2"><Field title="جنسیت"><select data-testid="profile-gender" className="input" value={draft.gender || ''} onChange={(e) => setDraft({ ...draft, gender: e.target.value })}><option value="">انتخاب نشده</option><option>زن</option><option>مرد</option><option>ترجیح می‌دهم نگویم</option></select></Field><Field title="شماره واتساپ"><input data-testid="profile-whatsapp" className="input" dir="ltr" value={draft.whatsapp || ''} onChange={(e) => setDraft({ ...draft, whatsapp: e.target.value.replace(/\D/g, '') })} /></Field><Field title="شناسه تلگرام"><input data-testid="profile-telegram" className="input" dir="ltr" value={draft.telegram || ''} onChange={(e) => setDraft({ ...draft, telegram: e.target.value })} /></Field><Field title="شناسه اینستاگرام"><input data-testid="profile-instagram" className="input" dir="ltr" value={draft.instagram || ''} onChange={(e) => setDraft({ ...draft, instagram: e.target.value })} /></Field><Field title="شناسه ایتا"><input data-testid="profile-eitaa" className="input" dir="ltr" value={draft.eitaa || ''} onChange={(e) => setDraft({ ...draft, eitaa: e.target.value })} /></Field><Field title="شناسه روبیکا"><input data-testid="profile-rubika" className="input" dir="ltr" value={draft.rubika || ''} onChange={(e) => setDraft({ ...draft, rubika: e.target.value })} /></Field></div><button data-testid="save-profile" onClick={() => void save()} className="min-h-11 w-full rounded-xl bg-[#12a05c] font-bold text-white">ذخیره تغییرات</button></div>}<div className="mt-5 flex items-center justify-between"><div><b className="text-sm">آگهی‌های من</b><p className="mt-1 text-[11px] text-zinc-500">به شکل پست‌های تصویری</p></div><button data-testid="profile-create" onClick={post} className="text-[11px] font-black text-[#12a05c]">ثبت آگهی +</button></div><div className="mt-3 grid grid-cols-3 gap-1.5 sm:gap-2">{ads.length ? ads.map((ad) => <div key={ad.id} className="relative aspect-square overflow-hidden rounded-xl"><button data-testid={'profile-ad-' + ad.id} onClick={() => openAd(ad)} className="size-full"><img src={ad.images[0] || PLACEHOLDER_IMAGE} alt={ad.title} className="size-full object-cover" /><span className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/70 to-transparent p-1.5 text-right text-[9px] font-black text-white">{toman(ad.price)}</span></button><button data-testid={'profile-edit-' + ad.id} onClick={() => edit(ad)} className="absolute left-1.5 top-1.5 grid size-8 place-items-center rounded-lg bg-white/90 text-[#0b7f47]"><Edit3 size={14} /></button></div>) : <div className="col-span-full rounded-3xl bg-white p-9 text-center text-sm text-zinc-500 dark:bg-[#17211e]">هنوز آگهی ثبت نکرده‌اید.</div>}</div></section>; }
function ManageScreen({ ads, me, reload, edit, back, notify }: { ads: Ad[]; me: User; reload: () => Promise<void>; edit: (a: Ad) => void; back: () => void; notify: (t: string) => void }) { const remove = async (ad: Ad) => { if (!window.confirm('این آگهی حذف شود؟')) return; try { const r = await fetch('/api/listings/' + ad.id + '?userId=' + me.id, { method: 'DELETE' }); if (!r.ok) throw new Error(); await reload(); notify('آگهی حذف شد.'); } catch { notify('حذف آگهی انجام نشد.'); } }; return <section className="mx-auto max-w-3xl"><button data-testid="manage-back" onClick={back} className="mb-2 min-h-10 text-xs text-zinc-500">بازگشت به پروفایل</button><h1 className="text-lg font-black">مدیریت آگهی‌های من</h1><div className="mt-4 space-y-2">{ads.length ? ads.map((ad) => <div data-testid={'manage-ad-' + ad.id} key={ad.id} className="flex gap-3 rounded-2xl bg-white p-3 dark:bg-[#17211e]"><img src={ad.images[0] || PLACEHOLDER_IMAGE} alt="" className="size-16 shrink-0 rounded-xl object-cover" /><div className="min-w-0 flex-1"><b className="line-clamp-1 text-sm">{ad.title}</b><p className="mt-1 text-xs font-bold text-[#12a05c]">{toman(ad.price)}</p><small className="text-[10px] text-zinc-500">{ad.isSpecial ? 'ویژه · ' : ''}{fnum(ad.views)} بازدید</small></div><button data-testid={'edit-ad-' + ad.id} onClick={() => edit(ad)} className="grid size-10 place-items-center self-center rounded-xl bg-emerald-50 text-[#0b7f47]"><Edit3 size={16} /></button><button data-testid={'delete-ad-' + ad.id} onClick={() => void remove(ad)} className="grid size-10 place-items-center self-center rounded-xl bg-rose-50 text-rose-600"><Trash2 size={16} /></button></div>) : <div className="rounded-3xl bg-white p-9 text-center text-sm text-zinc-500 dark:bg-[#17211e]">آگهی‌ای برای مدیریت وجود ندارد.</div>}</div></section>; }
function LocationSheet({ value, setValue, close }: { value: Filters; setValue: (value: Filters) => void; close: () => void }) { return <Sheet title="انتخاب استان، شهر و روستا" close={close} testId="city-modal"><LocationInputs value={value} onChange={(place) => setValue({ ...value, ...place })} ids={['location-province','location-county','location-village']} /><p className="mt-3 text-[11px] leading-6 text-zinc-500">نام شهر، شهرستان یا روستایی که در فهرست نیست را مستقیم بنویسید.</p><button data-testid="apply-location" onClick={close} className="mt-5 min-h-11 w-full rounded-xl bg-[#12a05c] text-sm font-bold text-white">تأیید موقعیت</button></Sheet>; }
function FilterSheet({ value, change, close }: { value: Filters; change: (v: Filters) => void; close: () => void }) { return <Sheet title="فیلترهای پیشرفته" close={close} testId="filter-sheet"><div className="space-y-3"><Field title="دسته‌بندی"><select data-testid="advanced-category" className="input" value={value.category} onChange={(e) => change({ ...value, category: e.target.value })}>{['همه',...categoryKeys].map((item) => <option key={item}>{item}</option>)}</select></Field><LocationInputs value={value} onChange={(place) => change({ ...value, ...place })} ids={['advanced-province','advanced-county','advanced-village']} /><div className="grid gap-3 sm:grid-cols-2"><Field title="کمترین قیمت"><input data-testid="min-price" className="input" inputMode="numeric" value={value.minPrice} onChange={(e) => change({ ...value, minPrice: e.target.value.replace(/\D/g, '') })} /></Field><Field title="بیشترین قیمت"><input data-testid="max-price" className="input" inputMode="numeric" value={value.maxPrice} onChange={(e) => change({ ...value, maxPrice: e.target.value.replace(/\D/g, '') })} /></Field></div><Field title="مرتب‌سازی"><select data-testid="sort-listings" className="input" value={value.sort} onChange={(e) => change({ ...value, sort: e.target.value })}><option value="newest">جدیدترین</option><option value="cheap">ارزان‌ترین</option><option value="expensive">گران‌ترین</option><option value="popular">پربازدیدترین</option></select></Field></div><div className="mt-5 grid grid-cols-2 gap-3"><button data-testid="reset-filters" onClick={() => change(emptyFilters)} className="min-h-11 rounded-xl bg-zinc-100 text-sm font-bold dark:bg-white/10">پاک کردن</button><button data-testid="apply-filters" onClick={close} className="min-h-11 rounded-xl bg-[#12a05c] text-sm font-bold text-white">نمایش آگهی‌ها</button></div></Sheet>; }
function StoryComposer({ me, close, refresh, notify }: { me: User; close: () => void; refresh: () => Promise<void>; notify: (t: string) => void }) { const [body, setBody] = useState(''); const [files, setFiles] = useState<File[]>([]); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const submit = async (event: FormEvent) => { event.preventDefault(); if (!body.trim() || !files[0]) return setError(!body.trim() ? 'متن استوری را بنویسید.' : 'یک تصویر برای استوری انتخاب کنید.'); setBusy(true); setError(''); try { const image = await uploadImage(files[0]); const response = await fetch('/api/stories', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ userId: me.id, body, image }) }); if (!response.ok) throw new Error('ثبت استوری انجام نشد.'); await refresh(); close(); notify('استوری شما منتشر شد.'); } catch (error) { setError(error instanceof Error ? error.message : 'ثبت استوری انجام نشد.'); } finally { setBusy(false); } }; return <Sheet title="افزودن استوری" close={close} testId="story-composer"><form onSubmit={submit} className="space-y-4"><p className="rounded-2xl bg-emerald-50 p-3 text-[11px] leading-6 text-zinc-600 dark:bg-emerald-950/20">استوری شما برای هر بیننده ۶۰ ثانیه نمایش داده می‌شود.</p><Field title="متن استوری"><textarea data-testid="story-body" className="input min-h-24 resize-none" value={body} onChange={(e) => setBody(e.target.value)} /></Field><Field title="تصویر استوری"><ImagePicker testId="story-image" files={files} setFiles={setFiles} single /></Field>{error && <p data-testid="story-error" className="rounded-xl bg-rose-50 p-3 text-xs font-bold text-rose-600">{error}</p>}<button data-testid="submit-story" disabled={busy} className="min-h-12 w-full rounded-xl bg-[#12a05c] text-sm font-black text-white disabled:opacity-60">{busy ? 'در حال انتشار...' : 'انتشار استوری'}</button></form></Sheet>; }
function StoryViewer({ story, close, move, notify, refresh, me }: { story: StoryItem; close: () => void; move: (n: number) => void; notify: (t: string) => void; refresh: () => Promise<void>; me: User }) { const [remaining, setRemaining] = useState(60); const [menu, setMenu] = useState(false); useEffect(() => { setRemaining(60); const timer = window.setInterval(() => setRemaining((n) => { if (n <= 1) { move(1); return 60; } return n - 1; }), 1000); return () => window.clearInterval(timer); }, [story.id, move]); const remove = async () => { try { const r = await fetch('/api/stories/' + story.id + '?userId=' + me.id, { method: 'DELETE' }); if (!r.ok) throw new Error(); await refresh(); close(); notify('استوری حذف شد.'); } catch { notify('فقط استوری خودتان قابل حذف است.'); } }; return <div data-testid="story-viewer" className="fixed inset-0 z-[70] grid place-items-center bg-black"><div className="relative h-[100dvh] w-full max-w-md overflow-hidden bg-[#101c17] sm:h-[92dvh] sm:rounded-3xl"><img src={story.image} alt="استوری" className="absolute size-full object-cover" /><div className="absolute inset-0 bg-gradient-to-b from-black/70 via-black/5 to-black/80" /><button data-testid="story-previous" onClick={() => move(-1)} className="absolute inset-y-20 right-0 z-[5] w-1/2" /><button data-testid="story-next" onClick={() => move(1)} className="absolute inset-y-20 left-0 z-[5] w-1/2" /><div className="absolute inset-x-0 top-0 z-10 p-4 pt-[calc(1rem+env(safe-area-inset-top))]"><div className="h-1 overflow-hidden rounded-full bg-white/30"><span className="block h-full bg-white" style={{ width: (remaining / 60) * 100 + '%' }} /></div><div className="mt-3 flex items-center gap-2 text-white"><button data-testid="story-close" onClick={close} className="grid size-9 place-items-center rounded-full bg-black/25"><X size={18} /></button><span className="grid size-10 overflow-hidden rounded-full border border-white/70 bg-[#12a05c]">{story.seller_avatar ? <img src={story.seller_avatar} alt="" className="size-full object-cover" /> : story.seller_name.slice(0,1)}</span><div className="min-w-0 flex-1"><b className="block truncate text-xs">{story.seller_name}</b><small className="block text-[10px] text-white/75">{story.county || story.city || story.province || 'پیدا'} · {fnum(remaining)} ثانیه</small></div><div className="relative"><button data-testid="story-menu" onClick={() => setMenu(!menu)} className="grid size-9 place-items-center rounded-full bg-black/25"><MoreHorizontal /></button>{menu && <div className="absolute left-0 top-11 w-44 rounded-2xl bg-white p-2 text-right text-zinc-700 shadow-2xl"><button data-testid="story-delete" onClick={() => void remove()} className="block w-full rounded-xl p-2 text-right text-sm text-rose-600">حذف استوری</button><button data-testid="story-viewers" onClick={() => notify(fnum(story.views) + ' نفر این استوری را دیده‌اند.')} className="block w-full rounded-xl p-2 text-right text-sm">مشاهده مخاطب</button><button data-testid="story-message" onClick={() => notify('از صفحه آگهی به آگهی‌دهنده پیام بدهید.')} className="block w-full rounded-xl p-2 text-right text-sm">پیام</button><button data-testid="story-report" onClick={() => notify('گزارش استوری ثبت شد.')} className="block w-full rounded-xl p-2 text-right text-sm">گزارش</button></div>}</div></div></div><div className="absolute inset-x-0 bottom-8 z-10 px-6 text-center text-white"><p className="rounded-2xl bg-black/30 px-4 py-3 text-sm leading-7">{story.body}</p><p data-testid="story-views" className="mt-4 text-xs"><Eye className="inline" size={15} /> {fnum(story.views)} بازدید</p><p className="mt-1 text-[10px] text-white/70">برای رفتن به قبل و بعد، سمت راست یا چپ تصویر را لمس کنید.</p></div></div></div>; }

type AdminTab = 'overview' | 'listings' | 'users' | 'messages' | 'sales' | 'sms';
type AdminUser = { id: number; name: string; phone: string; city: string; province: string; listing_count: number };
type AdminMessage = { id: number; body: string; sender_name: string; receiver_name: string; listing_title?: string };
type SmsSettings = { hasApiKey: boolean; keyHint: string; sender: string; template: string };
function AdminScreen({ leave, dark, toggleDark, notify }: { leave: () => void; dark: boolean; toggleDark: () => void; notify: (t: string) => void }) { const [token, setToken] = useState(localStorage.getItem('peida-admin-token') || ''); const [login, setLogin] = useState({ username: '', password: '' }); const [tab, setTab] = useState<AdminTab>('overview'); const [overview, setOverview] = useState<{users:number; listings:number; sold:number; messages:number; views:number} | null>(null); const [listings, setListings] = useState<Ad[]>([]); const [users, setUsers] = useState<AdminUser[]>([]); const [messages, setMessages] = useState<AdminMessage[]>([]); const [sms, setSms] = useState<SmsSettings | null>(null); const [smsForm, setSmsForm] = useState({ apiKey: '', sender: '', template: '', testPhone: '' }); const [error, setError] = useState(''); const load = useCallback(async (value: string) => { try { const headers = { 'x-admin-token': value }; const [a,b,c,d,e] = await Promise.all([fetch('/api/admin/overview',{headers}),fetch('/api/admin/listings',{headers}),fetch('/api/admin/users',{headers}),fetch('/api/admin/messages',{headers}),fetch('/api/admin/settings',{headers})]); if (a.status === 401) { localStorage.removeItem('peida-admin-token'); setToken(''); return; } if (!a.ok || !b.ok || !c.ok || !d.ok) throw new Error(); setOverview(await a.json()); setListings(await b.json()); setUsers(await c.json()); setMessages(await d.json()); if (e.ok) { const settings = await e.json() as SmsSettings; setSms(settings); setSmsForm((old) => ({ ...old, sender: settings.sender, template: settings.template })); } setError(''); } catch { setError('دریافت اطلاعات پنل انجام نشد.'); } }, []); useEffect(() => { if (token) void load(token); }, [token, load]); const enter = async (event: FormEvent) => { event.preventDefault(); try { const r = await fetch('/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(login)}); if(!r.ok) throw new Error(); const data = await r.json() as {token:string}; localStorage.setItem('peida-admin-token',data.token); setToken(data.token); } catch { setError('نام کاربری یا رمز عبور صحیح نیست.'); } }; const status = async (id:number, value:string) => { try { const r = await fetch('/api/admin/listings/'+id,{method:'PATCH',headers:{'Content-Type':'application/json','x-admin-token':token},body:JSON.stringify({status:value})}); if(!r.ok) throw new Error(); await load(token); notify('وضعیت آگهی به‌روزرسانی شد.'); } catch { notify('تغییر وضعیت انجام نشد.'); } }; const saveSms = async () => { try { const r = await fetch('/api/admin/settings',{method:'PUT',headers:{'Content-Type':'application/json','x-admin-token':token},body:JSON.stringify(smsForm)}); if(!r.ok) throw new Error(); setSmsForm({...smsForm,apiKey:''}); await load(token); notify('تنظیمات پیامک ذخیره شد.'); } catch { notify('ذخیره تنظیمات پیامک انجام نشد.'); } }; const testSms = async () => { try { const r = await fetch('/api/admin/settings/test',{method:'POST',headers:{'Content-Type':'application/json','x-admin-token':token},body:JSON.stringify({phone:smsForm.testPhone})}); if(!r.ok) throw new Error(); notify('درخواست ارسال پیامک آزمایشی ثبت شد.'); } catch { notify('ارسال پیامک آزمایشی ناموفق بود.'); } }; if(!token) return <div className="grid min-h-screen place-items-center bg-[#f4f6f5] p-4 dark:bg-[#0e1513]"><form onSubmit={enter} className="w-full max-w-md rounded-3xl bg-white p-6 shadow-xl dark:bg-[#17211e]"><button data-testid="admin-leave" type="button" onClick={leave} className="text-xs text-zinc-500">بازگشت به پیدا</button><div className="mt-5 flex items-center gap-3"><PeidaMark size={40}/><div><h1 className="font-black">پنل سازنده پیدا</h1><p className="text-[11px] text-zinc-500">دسترسی خصوصی مدیریت</p></div></div><input data-testid="admin-username" className="input mt-6" value={login.username} onChange={(e)=>setLogin({...login,username:e.target.value})} placeholder="نام کاربری"/><input data-testid="admin-password" className="input mt-3" dir="ltr" type="password" value={login.password} onChange={(e)=>setLogin({...login,password:e.target.value})} placeholder="رمز عبور"/>{error&&<p className="mt-3 text-sm text-rose-600">{error}</p>}<button data-testid="admin-login" className="mt-4 min-h-12 w-full rounded-xl bg-[#12a05c] font-black text-white">ورود به پنل</button></form></div>; const sold = listings.filter((a)=>a.status==='sold'); const value=sold.reduce((n,a)=>n+a.price,0); return <div className="min-h-screen bg-[#f4f6f5] pb-10 dark:bg-[#0e1513] dark:text-white"><header className="border-b border-zinc-200 bg-white dark:border-white/10 dark:bg-[#17211e]"><div className="mx-auto flex min-h-16 max-w-6xl flex-wrap items-center justify-between gap-2 px-4"><div className="flex items-center gap-2"><PeidaMark size={32}/><b className="text-sm">پنل سازنده</b></div><div className="flex gap-2"><button data-testid="admin-theme" onClick={toggleDark} className="grid size-10 place-items-center rounded-xl bg-zinc-100 dark:bg-white/10">{dark?<Sun size={17}/>:<Moon size={17}/>}</button><button onClick={leave} className="min-h-10 rounded-xl bg-zinc-100 px-3 text-xs dark:bg-white/10">مشاهده اپ</button><button data-testid="admin-logout" onClick={()=>{localStorage.removeItem('peida-admin-token');setToken('')}} className="min-h-10 rounded-xl bg-zinc-100 px-3 text-xs dark:bg-white/10">خروج</button></div></div></header><main className="mx-auto w-full max-w-6xl px-4 py-5"><div className="mb-4 flex gap-2 overflow-x-auto pb-1 scrollless">{([['overview','نمای کلی'],['listings','آگهی‌ها'],['users','مخاطبان'],['messages','پیام‌ها'],['sales','گزارش فروش'],['sms','پیامک']] as [AdminTab,string][]).map(([key,label])=><button data-testid={'admin-tab-'+key} key={key} onClick={()=>setTab(key)} className={'min-h-10 shrink-0 rounded-xl px-4 text-xs font-bold '+(tab===key?'bg-[#12a05c] text-white':'bg-white dark:bg-[#17211e]')}>{label}</button>)}</div>{error&&<p className="mb-3 text-sm text-rose-600">{error}</p>}{tab==='overview'&&<div className="grid grid-cols-2 gap-3 lg:grid-cols-5">{[['مخاطبان',overview?.users],['آگهی فعال',overview?.listings],['فروخته‌شده',overview?.sold],['پیام‌ها',overview?.messages],['بازدید کل',overview?.views]].map(([title,count])=><div key={String(title)} className="rounded-2xl bg-white p-4 dark:bg-[#17211e]"><b className="text-xl text-[#12a05c]">{count===undefined?'—':fnum(Number(count))}</b><p className="mt-2 text-[11px] text-zinc-500">{title}</p></div>)}</div>}{tab==='listings'&&<div className="space-y-2">{listings.map((item)=><div key={item.id} className="flex flex-wrap items-center gap-3 rounded-2xl bg-white p-3 dark:bg-[#17211e]"><img src={item.images[0]||PLACEHOLDER_IMAGE} alt="" className="size-14 rounded-xl object-cover"/><div className="min-w-0 flex-1"><b className="block truncate text-sm">{item.title}</b><small>{item.seller_name} · {toman(item.price)}</small></div><select value={item.status||'active'} onChange={(e)=>void status(item.id,e.target.value)} className="input !min-h-10 w-36"><option value="active">فعال</option><option value="paused">متوقف</option><option value="sold">فروخته شده</option><option value="deleted">حذف شده</option></select></div>)}</div>}{tab==='users'&&<div className="overflow-x-auto rounded-2xl bg-white dark:bg-[#17211e]"><table className="w-full min-w-[520px] text-right text-xs"><thead><tr><th className="p-3">نام</th><th className="p-3">شماره</th><th className="p-3">موقعیت</th><th className="p-3">آگهی</th></tr></thead><tbody>{users.map((user)=><tr key={user.id} className="border-t border-zinc-100 dark:border-white/10"><td className="p-3">{user.name}</td><td className="p-3" dir="ltr">{user.phone}</td><td className="p-3">{user.province} {user.city}</td><td className="p-3">{fnum(user.listing_count)}</td></tr>)}</tbody></table></div>}{tab==='messages'&&<div className="space-y-2">{messages.map((message)=><div key={message.id} className="rounded-2xl bg-white p-3 text-sm dark:bg-[#17211e]"><p className="text-[11px] text-zinc-500">{message.sender_name} ← {message.receiver_name} {message.listing_title?'· '+message.listing_title:''}</p><p className="mt-1">{message.body}</p></div>)}</div>}{tab==='sales'&&<div className="grid grid-cols-2 gap-3"><div className="rounded-2xl bg-white p-4 dark:bg-[#17211e]"><b className="text-xl text-[#12a05c]">{fnum(sold.length)}</b><p className="text-xs text-zinc-500">تعداد فروش</p></div><div className="rounded-2xl bg-white p-4 dark:bg-[#17211e]"><b className="text-xl text-[#12a05c]">{toman(value)}</b><p className="text-xs text-zinc-500">ارزش کل فروش</p></div></div>}{tab==='sms'&&<div className="max-w-xl space-y-4 rounded-2xl bg-white p-5 dark:bg-[#17211e]"><div><b>اتصال کاوه‌نگار</b><p className="mt-2 text-[11px] leading-6 text-zinc-500">کلید دسترسی و خط ارسال را وارد کنید؛ این مقادیر فقط روی سرور نگهداری می‌شوند.</p><p data-testid="sms-state" className="mt-3 rounded-xl bg-emerald-50 p-3 text-[11px] text-[#0b7f47]">{sms?.hasApiKey?'کلید ثبت شده است: '+sms.keyHint:'کلید کاوه‌نگار هنوز ثبت نشده است.'}</p></div><Field title="کلید دسترسی"><input data-testid="sms-api-key" className="input" dir="ltr" value={smsForm.apiKey} onChange={(e)=>setSmsForm({...smsForm,apiKey:e.target.value})}/></Field><div className="grid gap-3 sm:grid-cols-2"><Field title="خط ارسال"><input data-testid="sms-sender" className="input" dir="ltr" value={smsForm.sender} onChange={(e)=>setSmsForm({...smsForm,sender:e.target.value})}/></Field><Field title="نام الگو (اختیاری)"><input data-testid="sms-template" className="input" dir="ltr" value={smsForm.template} onChange={(e)=>setSmsForm({...smsForm,template:e.target.value})}/></Field></div><button data-testid="sms-save" onClick={()=>void saveSms()} className="min-h-11 w-full rounded-xl bg-[#12a05c] text-sm font-black text-white">ذخیره تنظیمات پیامک</button><Field title="ارسال پیامک آزمایشی"><div className="flex gap-2"><input data-testid="sms-test-phone" className="input min-w-0 flex-1" dir="ltr" value={smsForm.testPhone} onChange={(e)=>setSmsForm({...smsForm,testPhone:e.target.value.replace(/\D/g,'').slice(0,11)})}/><button data-testid="sms-test" onClick={()=>void testSms()} className="min-h-11 rounded-xl bg-emerald-50 px-4 text-xs font-bold text-[#0b7f47]">ارسال تست</button></div></Field></div>}</main></div>; }
